const intent={id:'care',content:'照顧自己的生活',context:'具體來源與方法可以改變',intensity:'medium',importance:'medium',urgency:'medium'};
const action=(type,target,content,purpose='')=>({type,target,content,purpose,mood:'平靜',durationMinutes:15,timeIntent:{kind:type==='rest'||type==='reflect'?'open-ended':'completion',maxMinutes:null},intents:[intent]});
const supply=(id,label,kind,extra={})=>({id,label,kind,region:'cafe-front',owner:'owner',knownTo:['owner'],allowedTo:['owner'],remaining:1,initialState:{},consumable:false,quantity:{amount:1,unit:'item'},...extra});
const item=(id,label,kind,state,extra={})=>({id,label,kind,state,source:'explicit-fixture',region:'cafe-front',holder:'owner',owner:'owner',revision:1,lifecycle:'active',consumable:kind==='drink',quantity:{amount:1,unit:'item'},knownTo:['owner'],allowedTo:['owner'],...extra});
function initialWorld(seedWorld,{hidden='SECRET_A',peer=true}={}){
 const w=seedWorld();w.contextId='method-reassessment-integration-fixture';w.pursuitContext='synthetic-method-reassessment-v3';w.characters=w.characters.filter(c=>c.id==='owner'||peer&&c.id==='cass').sort((a,b)=>Number(b.id==='owner')-Number(a.id==='owner'));w.characters.forEach(c=>{c.location='cafe';c.region='cafe-front';c.shortTerm=[];c.longTerm=[];c.memories=[];c.intents=[...c.intents,savedPursuit(c.id,intent)];});w.adjudication={provider:'openai',model:'fixture-judge'};
 w.objects=[item('old-cup','舊杯子','utensil',{contents:'tea'}),item('old-tea','舊杯中的茶','drink',{vessel:'old-cup',beverage:'tea'}),item('new-cup','新茶杯','utensil',{contents:'empty'})];w.supplies=[supply('meal-source','指定那份餐點','food',{consumable:true}),supply('leaves','另一份茶葉','tea-leaves'),supply('water-source','一份飲用水','drinking-water')];w.scene.external={'cafe-front':{revision:1,state:{'private-stock':hidden},exposure:{'private-stock':'hidden'}}};return w;
}
function preparation(){return f.program('prepare-flatbread','用另一個來源的麵粉做一份薄餅','準備食物',[f.binding('raw','supply','local',[],{kind:'food',sourceRole:'material',sourceSubject:'麵粉',background:f.bg('普通麵粉','food')})],[f.phase(15,[{kind:'materialize',supplyId:'$raw',expectedRemaining:0},f.form('新做的一份薄餅','meal')])]);}
function take(){const p=f.program('take-meal','取用指定餐點','用餐',[f.binding('meal','supply','target',[],{kind:'food'})],[f.phase(15,[{kind:'materialize',supplyId:'$meal',expectedRemaining:0}])]);p.methods[0].aliases=[{content:'拿取這份餐點',purpose:'食用'}];return p;}
function eat(){const p=f.program('eat-food','吃這份食物','進食',[f.binding('food','object','target')],[f.phase(15,[{kind:'ingest',version:1,objectId:'$food',expectedRevision:0,hungerRelief:12,thirstRelief:0}])]);p.methods[0].aliases=[{content:'食用這份餐點',purpose:'用餐'}];return p;}
function drink(){return f.program('finish-tea','喝完這杯茶','飲用',[f.binding('drink','object','target',[{key:'beverage',value:'tea'}],{kind:'drink'}),f.binding('vessel','object','linked',[{key:'contents',value:'tea'}],{kind:'utensil',link:{role:'drink',key:'vessel',direction:'from-role'}})],[f.phase(15,[{kind:'ingest',version:1,objectId:'$drink',expectedRevision:0,hungerRelief:0,thirstRelief:12},f.change('vessel','contents','tea','empty')])]);}
function brew(){return f.program('prepare-infusion','用另一份茶葉在新杯泡茶','準備茶',[f.binding('vessel','object','target',[{key:'contents',value:'empty'}],{kind:'utensil'}),f.binding('raw','supply','local',[],{kind:'tea-leaves',sourceRole:'material',sourceSubject:'茶葉'})],[f.phase(15,[{kind:'materialize',supplyId:'$raw',expectedRemaining:0},{...f.form('新泡的一杯茶','drink',[{key:'vessel',value:'$vessel',exposure:'public'},{key:'beverage',value:'tea',exposure:'public'}]),outputs:[{id:'$product',label:'新泡的一杯茶',kind:'drink',consumable:true,quantity:{amount:1,unit:'item'},state:[{key:'vessel',value:'$vessel',exposure:'public'},{key:'beverage',value:'tea',exposure:'public'}]}]},f.change('vessel','contents','empty','tea')])]);}
function sip(initial){
 const p=f.program(initial?'divide-and-sip':'sip-quarter','喝幾口這杯茶','飲用',[f.binding('vessel','object','target',[{key:'contents',value:'tea'}],{kind:'utensil'}),f.binding('drink','object','linked',[{key:'beverage',value:'tea'}],{kind:'drink',link:{role:'vessel',key:'vessel',direction:'to-role'},quantity:{amount:initial?1:2,unit:initial?'item':'quarter-serving'}})],[]);
 p.methods[0].aliases=[{content:'小口飲用杯中茶',purpose:'喝茶'}];const effects=initial?[{kind:'form',version:1,access:'authorized',operation:'partition',inputs:[{objectId:'$drink',expectedRevision:0,quantity:{amount:1,unit:'item'},disposition:'consumed'}],outputs:[{id:'$measured',label:'同杯茶的四等份整體',kind:'drink',consumable:true,quantity:{amount:4,unit:'quarter-serving'},state:[{key:'vessel',value:'$vessel',exposure:'public'},{key:'beverage',value:'tea',exposure:'public'}]}],reason:'只改同杯茶的追蹤粒度，不新增茶或推定毫升。'}]:[];
 effects.push({kind:'separate',version:1,access:'authorized',objectId:initial?'$measured':'$drink',expectedRevision:0,quantity:{amount:1,unit:'quarter-serving'},outputId:'$sip',reason:'真正取出一份攝取，其他份額留在原杯。'},{kind:'ingest',version:1,objectId:'$sip',expectedRevision:0,hungerRelief:0,thirstRelief:3});p.stages=[f.phase(15,effects)];return p;
}
function finishQuarter(){const p=drink();p.operation='finish-quarter';p.methods=[{content:'喝完最後一份茶',purpose:'飲用'}];p.bindings[0].quantity={amount:1,unit:'quarter-serving'};p.stages[0].effects[0].thirstRelief=3;return p;}
function water(){return f.program('pour-water','在咖啡館把飲用水倒入空杯','準備飲水',[f.binding('vessel','object','local',[{key:'contents',value:'empty'}],{kind:'utensil',label:'新茶杯'}),f.binding('raw','supply','local',[],{kind:'drinking-water',sourceRole:'material',sourceSubject:'飲用水'})],[f.phase(15,[{kind:'materialize',supplyId:'$raw',expectedRemaining:0},f.form('新取得的飲用水','drink',[{key:'vessel',value:'$vessel',exposure:'public'},{key:'beverage',value:'water',exposure:'public'}]),f.change('vessel','contents','empty','water')])]);}
function drinkWater(){const p=drink();p.operation='drink-water';p.methods=[{content:'喝下新取得的飲用水',purpose:'飲水'}];p.bindings[0].state=[{key:'beverage',value:'water'}];p.bindings[1].state=[{key:'contents',value:'water'}];p.stages[0].effects[0].thirstRelief=4;p.stages[0].effects[1]=f.change('vessel','contents','water','empty');return p;}
const visible=(input,predicate)=>{const result=input.objects.find(predicate);assert.ok(result,'Explicit fixture could not find a legally visible current object');return result.id;};
function decision(step,input){
 let a;if(input.self.id==='cass')a=step==='ask'?action('say','owner','我現在不另外製作；你可以自己決定要不要準備。'):action('rest','','我先坐一會兒');
 else switch(step){
  case'take':case'retry':a=action('propose','meal-source',step==='retry'?'拿取這份餐點':'取用指定餐點',step==='retry'?'食用':'用餐');break;
  case'eat-old':case'eat-new':a=action('propose',visible(input,o=>o.kind==='food'||o.kind==='meal'),step==='eat-old'?'吃這份食物':'食用這份餐點',step==='eat-old'?'進食':'用餐');break;
  case'ask':a=action('say','cass','你願意幫我另外準備食物嗎？');break;
  case'prepare':a=action('propose','cafe','用另一個來源的麵粉做一份薄餅','準備食物');break;
  case'old-tea':a=action('propose','old-tea','喝完這杯茶','飲用');break;
  case'brew':a=action('propose','new-cup','用另一份茶葉在新杯泡茶','準備茶');break;
  case'sip-item':case'sip-quarter':case'sip-alias':a=action('propose','new-cup',step==='sip-alias'?'小口飲用杯中茶':'喝幾口這杯茶',step==='sip-alias'?'喝茶':'飲用');break;
  case'finish':a=action('propose',visible(input,o=>o.kind==='drink'&&o.quantity?.unit==='quarter-serving'),'喝完最後一份茶','飲用');break;
  case'water':a=action('propose','cafe','在咖啡館把飲用水倒入空杯','準備飲水');break;
  case'drink-water':a=action('propose',visible(input,o=>o.state.beverage==='water'),'喝下新取得的飲用水','飲水');break;
  default:a=action('reflect','','想想剛才的經歷');
 }
 const entries=input.self.lastKnownState?.entries||[],known=entries.filter(e=>e.reference.kind==='short'||e.reference.kind==='long').slice(0,2).map(e=>e.reference);
 return wire(a,{purpose:'照顧自己的生活',knownResults:known,choice:step==='retry'?'retry':['prepare','brew','water'].includes(step)?'switch':'new',change:{kind:['prepare','brew','water'].includes(step)?'source':'not-applicable',detail:['prepare','brew','water'].includes(step)?'改用不同來源與本次準備步驟':''},reason:'根據我此刻保留的經歷選擇，結果不等於現在仍有庫存。'});
}
function model(){let step='take',npc=0,judgments=0;const frames=[];return {setStep:s=>{step=s;},counts:()=>({npc,judgments}),frames,respond(request){const input=JSON.parse(request.messages[1].content);let value;if(input.contractVersion==='world-adjudication.v1'){judgments++;const programs={take,eat:eat,'eat-old':eat,prepare:preparation,'old-tea':drink,brew,'sip-item':()=>sip(true),'sip-quarter':()=>sip(false),finish:finishQuarter,water,'drink-water':drinkWater};assert.ok(programs[step],`Unexpected new adjudication in ${step}`);const p=programs[step]();value=f.approval([p],p.operation,'生活方法');}else{npc++;value=decision(step,input);}frames.push({step,request,input,value});return Response.json({usage:{prompt_tokens:30,completion_tokens:10},choices:[{message:{content:JSON.stringify(fixturePursuitDecision(JSON.parse(request.messages[1].content),value))}}]});}};}
module.exports={initialWorld,model,intent,action};
